import{a as e,i as t,r as n,s as r,t as i}from"./app-CchzzT6L.js";var a=JSON.parse(`{"path":"/n8n/","title":"สร้างเครื่องผลิตคลิปสั้นไวรัล","lang":"en-US","frontmatter":{},"git":{"updatedTime":1748677577000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":2,"url":"https://github.com/hifat"}],"changelog":[{"hash":"1befd4062c8715aa2a74f4a8c539ca927fc7fae2","time":1748677577000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add youtube content"},{"hash":"9cd4d9fa111dbc21f643ce20316b1f4d75d3f2ed","time":1747386869000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add n8n content"}]},"filePathRelative":"n8n/README.md"}`),o={name:`README.md`};function s(i,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[n(`h1`,{id:`สร้างเครื่องผลิตคลิปสั้นไวรัล`,tabindex:`-1`},[n(`a`,{class:`header-anchor`,href:`#สร้างเครื่องผลิตคลิปสั้นไวรัล`},[n(`span`,null,`สร้างเครื่องผลิตคลิปสั้นไวรัล`)])],-1),n(`iframe`,{width:`100%`,height:`500`,src:`https://www.youtube.com/embed/sn10TLmukPI`,title:`No Code สร้างเครื่องผลิตคลิปสั้นไวรัล ด้วย AI + n8n ในคลิปเดียว! || ด้วยงบ 1 บาท/คลิป!`,frameborder:`0`,allow:`accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share`,referrerpolicy:`strict-origin-when-cross-origin`,allowfullscreen:``},null,-1),e(`<p>ตามคลิปวิดีโอที่คุณให้มา สามารถสรุปขั้นตอนการสร้างคลิปสั้นไวรัลเกี่ยวกับสัตว์ด้วย AI และ n8n ได้ดังนี้:</p><p><strong>1. การติดตั้ง n8n:</strong></p><ul><li>ดาวน์โหลดและติดตั้ง Docker [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=88" target="_blank" rel="noopener noreferrer">01:28</a>]</li><li>ค้นหา &quot;n8n&quot; ใน Docker Hub และเลือกตัวที่มีการดาวน์โหลดจำนวนมาก (100 ล้านครั้ง) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=102" target="_blank" rel="noopener noreferrer">01:42</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=106" target="_blank" rel="noopener noreferrer">01:46</a>]</li><li>ทำการ &quot;Pull&quot; และ &quot;Run&quot; [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=108" target="_blank" rel="noopener noreferrer">01:48</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=112" target="_blank" rel="noopener noreferrer">01:52</a>]</li><li>เข้าใช้งาน n8n ผ่าน <code>Local Host:5678</code> [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=117" target="_blank" rel="noopener noreferrer">01:57</a>]</li><li>สมัครสมาชิกและเข้าสู่ระบบ [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=127" target="_blank" rel="noopener noreferrer">02:07</a>]</li></ul><p><strong>2. การเตรียม Google Cloud:</strong></p><ul><li>Import template &quot;when clicking test workflow for&quot; ใน n8n หรือดาวน์โหลดไฟล์ template และ Import ใน Google Sheet [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=147" target="_blank" rel="noopener noreferrer">02:27</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=153" target="_blank" rel="noopener noreferrer">02:33</a>]</li><li>สร้าง Google Sheet ใหม่ใน n8n [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=162" target="_blank" rel="noopener noreferrer">02:42</a>]</li><li>สร้าง Credential ใหม่สำหรับ Google Sheet [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=172" target="_blank" rel="noopener noreferrer">02:52</a>]</li><li>สร้าง Project ใหม่ใน Google Cloud Console หรือเลือก Project ที่มีอยู่ [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=181" target="_blank" rel="noopener noreferrer">03:01</a>]</li><li>เปิดใช้งาน Google Sheets API [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=202" target="_blank" rel="noopener noreferrer">03:22</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=208" target="_blank" rel="noopener noreferrer">03:28</a>]</li><li>ตั้งค่า OAuth consent screen โดยใส่ชื่อแอปและอีเมลสนับสนุนผู้ใช้ [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=218" target="_blank" rel="noopener noreferrer">03:38</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=228" target="_blank" rel="noopener noreferrer">03:48</a>]</li><li>สร้าง Client ID ประเภท Web application และใส่ Authorized redirect URIs จาก n8n [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=252" target="_blank" rel="noopener noreferrer">04:12</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=267" target="_blank" rel="noopener noreferrer">04:27</a>]</li><li>คัดลอก Client ID และ Client Secret ไปวางใน n8n [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=277" target="_blank" rel="noopener noreferrer">04:37</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=282" target="_blank" rel="noopener noreferrer">04:42</a>]</li><li>เพิ่ม Test users ใน OAuth consent screen โดยใส่อีเมลที่ต้องการให้เข้าถึง Google Sheet [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=292" target="_blank" rel="noopener noreferrer">04:52</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=297" target="_blank" rel="noopener noreferrer">04:57</a>]</li><li>Sign in with Google ใน n8n และอนุญาตการเข้าถึง [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=312" target="_blank" rel="noopener noreferrer">05:12</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=320" target="_blank" rel="noopener noreferrer">05:20</a>]</li><li>ตรวจสอบการเชื่อมต่อ Google Sheet โดยดูที่ Form List ใน n8n [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=336" target="_blank" rel="noopener noreferrer">05:36</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=342" target="_blank" rel="noopener noreferrer">05:42</a>]</li></ul><p><strong>3. การสร้าง Google Sheet สำหรับข้อมูล:</strong></p><ul><li>สร้างไฟล์ Google Sheet และใส่ข้อมูลในแต่ละคอลัมน์ (1.1 ถึง 8.3) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=352" target="_blank" rel="noopener noreferrer">05:52</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=357" target="_blank" rel="noopener noreferrer">05:57</a>]</li><li>ตั้งชื่อ Sheet เป็น &quot;Sheet1&quot; และมีคอลัมน์ &quot;status&quot; และ &quot;to do&quot; (สำหรับค่าที่จะนำไปสร้างคลิป) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=363" target="_blank" rel="noopener noreferrer">06:03</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=367" target="_blank" rel="noopener noreferrer">06:07</a>]</li><li>ในส่วนของ Agent ใน n8n ให้ดึงข้อมูลจาก Google Sheet ในคอลัมน์ที่ต้องการ เช่น Main Character และ Opponent [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=382" target="_blank" rel="noopener noreferrer">06:22</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=392" target="_blank" rel="noopener noreferrer">06:32</a>]</li><li>ใส่ Prompt สำหรับสร้างคลิป Animal vs Animal [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=406" target="_blank" rel="noopener noreferrer">06:46</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=411" target="_blank" rel="noopener noreferrer">06:51</a>]</li></ul><p><strong>4. การตั้งค่า Open AI:</strong></p><ul><li>เข้าไปที่ OpenAI Platform และเติมเงิน (แนะนำ 5 ดอลลาร์) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=424" target="_blank" rel="noopener noreferrer">07:04</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=464" target="_blank" rel="noopener noreferrer">07:44</a>]</li><li>สร้าง Secret Key ใหม่และคัดลอก Key [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=473" target="_blank" rel="noopener noreferrer">07:53</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=477" target="_blank" rel="noopener noreferrer">07:57</a>]</li><li>ใน n8n ที่ Open AI ให้สร้าง Credential ใหม่และวาง Secret Key [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=483" target="_blank" rel="noopener noreferrer">08:03</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=487" target="_blank" rel="noopener noreferrer">08:07</a>]</li></ul><p><strong>5. การสร้าง Scene ใน n8n:</strong></p><ul><li>พิมพ์ข้อความสำหรับ Scene โดยดึงข้อมูล Main Character และ Opponent จาก Google Sheet [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=498" target="_blank" rel="noopener noreferrer">08:18</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=520" target="_blank" rel="noopener noreferrer">08:40</a>]</li><li>ใช้ Node &quot;Split Out&quot; กับ Opponent [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=525" target="_blank" rel="noopener noreferrer">08:45</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=531" target="_blank" rel="noopener noreferrer">08:51</a>]</li><li>ใช้ Node &quot;Merge&quot; เพื่อรวมข้อมูล [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=542" target="_blank" rel="noopener noreferrer">09:02</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=551" target="_blank" rel="noopener noreferrer">09:11</a>]</li><li>สร้าง Agent อีกครั้งและตั้งชื่อ (เช่น main animal opponent) พร้อมใส่ข้อมูล Prompt [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=563" target="_blank" rel="noopener noreferrer">09:23</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=589" target="_blank" rel="noopener noreferrer">09:49</a>]</li><li>ใช้ Model &quot;GPT-4 1106-preview&quot; [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=597" target="_blank" rel="noopener noreferrer">09:57</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=603" target="_blank" rel="noopener noreferrer">10:03</a>]</li><li>ตั้งค่า Close Up [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=603" target="_blank" rel="noopener noreferrer">10:03</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=608" target="_blank" rel="noopener noreferrer">10:08</a>]</li><li>ใช้ &quot;Split Out&quot; อีกครั้ง [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=608" target="_blank" rel="noopener noreferrer">10:08</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=613" target="_blank" rel="noopener noreferrer">10:13</a>]</li><li>ใช้ Node &quot;Loop Over Items&quot; โดยตั้ง Bat Size เป็น 1 [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=613" target="_blank" rel="noopener noreferrer">10:13</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=618" target="_blank" rel="noopener noreferrer">10:18</a>]</li><li>เชื่อมต่อ Loop ไปที่ Node &quot;Merge&quot; [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=625" target="_blank" rel="noopener noreferrer">10:25</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=630" target="_blank" rel="noopener noreferrer">10:30</a>]</li><li>ตั้งค่า Wait Node (เช่น 15 วินาที) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=641" target="_blank" rel="noopener noreferrer">10:41</a>]</li></ul><p><strong>6. การตั้งค่า Together AI (สำหรับสร้างรูปภาพฟรี):</strong></p><ul><li>เข้าไปที่เว็บไซต์ Together AI และล็อกอินด้วย Gmail [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=648" target="_blank" rel="noopener noreferrer">10:48</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=667" target="_blank" rel="noopener noreferrer">11:07</a>]</li><li>คัดลอก API Key ที่อยู่ด้านล่างสุด [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=672" target="_blank" rel="noopener noreferrer">11:12</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=676" target="_blank" rel="noopener noreferrer">11:16</a>]</li><li>ใน n8n ที่ Together AI สร้าง Credential ใหม่ [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=702" target="_blank" rel="noopener noreferrer">11:42</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=707" target="_blank" rel="noopener noreferrer">11:47</a>]</li><li>ใส่ &quot;Authorization&quot; ใน Header และ &quot;Bearer [API Key]&quot; ใน Value (อย่าลืมเว้นวรรคหลัง Bearer) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=713" target="_blank" rel="noopener noreferrer">11:53</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=718" target="_blank" rel="noopener noreferrer">11:58</a>]</li><li>ติ๊ก &quot;S Body&quot; และตั้งค่า JSON [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=739" target="_blank" rel="noopener noreferrer">12:19</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=745" target="_blank" rel="noopener noreferrer">12:25</a>]</li></ul><p><strong>7. การสร้าง Code และอัปเดต Google Sheet:</strong></p><ul><li>ใช้ Node &quot;Code&quot; เพื่อรวม URL รูปภาพที่สร้างทั้งหมด [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=752" target="_blank" rel="noopener noreferrer">12:32</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=770" target="_blank" rel="noopener noreferrer">12:50</a>]</li><li>สร้าง Google Sheet ใหม่สำหรับอัปเดตข้อมูล [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=792" target="_blank" rel="noopener noreferrer">13:12</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=798" target="_blank" rel="noopener noreferrer">13:18</a>]</li><li>ใช้ Node &quot;Google Sheet&quot; เลือก &quot;Update a Row&quot; และตั้งค่า Document ID, Sheet Name และ Column ต่างๆ โดยดึงข้อมูลจาก Node ก่อนหน้า [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=798" target="_blank" rel="noopener noreferrer">13:18</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=804" target="_blank" rel="noopener noreferrer">13:24</a>]</li><li>คัดลอก Workflow ทั้งหมด (Ctrl+C) และวาง (Ctrl+V) เพื่อสร้าง Workflow ส่วนล่างที่คล้ายกัน [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=830" target="_blank" rel="noopener noreferrer">13:50</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=834" target="_blank" rel="noopener noreferrer">13:54</a>]</li><li>ปรับ Model ใน Workflow ส่วนล่างเป็น &quot;GPT-4 1106-preview&quot; [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=839" target="_blank" rel="noopener noreferrer">13:59</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=844" target="_blank" rel="noopener noreferrer">14:04</a>]</li><li>ตั้งค่า Prompt ใน Agent สำหรับ Animal 1 vs Animal 2 [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=849" target="_blank" rel="noopener noreferrer">14:09</a>]</li><li>ตั้งค่า System Message [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=855" target="_blank" rel="noopener noreferrer">14:15</a>]</li><li>ปรับค่า Width และ Height ใน Node &quot;Generate Scene&quot; [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=870" target="_blank" rel="noopener noreferrer">14:30</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=875" target="_blank" rel="noopener noreferrer">14:35</a>]</li><li>ปรับ Node &quot;Add Winner&quot; โดยเพิ่ม Column (1.2, 1.3) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=884" target="_blank" rel="noopener noreferrer">14:44</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=889" target="_blank" rel="noopener noreferrer">14:49</a>]</li><li>ใช้ Node &quot;Google Sheet&quot; เลือก &quot;Update a Row&quot; อีกครั้ง [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=895" target="_blank" rel="noopener noreferrer">14:55</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=909" target="_blank" rel="noopener noreferrer">15:09</a>]</li><li>ใช้ Node &quot;Merge&quot; เพื่อ Combine Position [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=915" target="_blank" rel="noopener noreferrer">15:15</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=920" target="_blank" rel="noopener noreferrer">15:20</a>]</li><li>ใช้ Node &quot;Get Element of&quot; จาก Google Sheet (Get Low) [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=926" target="_blank" rel="noopener noreferrer">15:26</a>]</li></ul><p><strong>8. การตั้งค่า Render Video:</strong></p><ul><li>ใช้ Node &quot;Create a Mate&quot; โดยสมัครสมาชิกและล็อกอินบนเว็บไซต์ Mate [<a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=937" target="_blank" rel="noopener noreferrer">15:37</a>, <a href="http://www.youtube.com/watch?v=sn10TLmukPI&amp;t=949" target="_blank" rel="noopener noreferrer">15:49</a>]</li><li>สร้าง Template ใหม่ใน Mate และใส่ Code Template ที่ผู้สอนให้ (โดยการ Copy Code ไปวาง)</li></ul>`,17)]])}var c=i(o,[[`render`,s]]);export{a as _pageData,c as default};